ALTER TABLE public.customer_coupons ADD COLUMN discount_type text NOT NULL DEFAULT 'percent', ADD COLUMN discount_value numeric NOT NULL DEFAULT 0, ADD COLUMN min_order numeric NOT NULL DEFAULT 0;
ALTER TABLE public.customer_coupons ADD CONSTRAINT customer_coupons_discount_check CHECK (discount_type IN ('percent', 'fixed') AND discount_value >= 0 AND min_order >= 0 AND (discount_type <> 'percent' OR discount_value <= 100));
ALTER TABLE public.orders ADD COLUMN coupon_id uuid, ADD COLUMN discount_amount numeric NOT NULL DEFAULT 0;
CREATE FUNCTION public.admin_find_user_by_email(lookup text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, auth AS $$ SELECT id FROM auth.users WHERE lower(email) = lower(btrim(lookup)) LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.admin_find_user_by_email(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_find_user_by_email(text) TO service_role;
DROP FUNCTION public.create_owned_order(jsonb, jsonb, uuid);
CREATE FUNCTION public.create_owned_order(order_data jsonb, items jsonb, owner_id uuid DEFAULT NULL, coupon_code text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE created_id uuid; cp public.customer_coupons; coupon_text text := NULLIF(btrim(coupon_code), ''); subtotal numeric; discount numeric := 0; BEGIN IF coupon_text IS NOT NULL THEN IF owner_id IS NULL THEN RAISE EXCEPTION 'Sign in to use a coupon'; END IF; SELECT * INTO cp FROM public.customer_coupons c WHERE c.user_id = owner_id AND upper(c.code) = upper(coupon_text) AND c.used_at IS NULL AND (c.expires_at IS NULL OR c.expires_at > now()) ORDER BY c.expires_at NULLS LAST, c.id LIMIT 1 FOR UPDATE; IF cp.id IS NULL THEN RAISE EXCEPTION 'Coupon is invalid, expired or already used'; END IF; IF cp.discount_value <= 0 THEN RAISE EXCEPTION 'Coupon has no discount value'; END IF; END IF; created_id := public.create_order_with_items(order_data, items); IF cp.id IS NOT NULL THEN SELECT COALESCE(SUM(unit_price * quantity), 0) INTO subtotal FROM public.order_items WHERE order_id = created_id; IF subtotal < cp.min_order THEN RAISE EXCEPTION 'Order total is below the coupon minimum'; END IF; discount := LEAST(subtotal, CASE WHEN cp.discount_type = 'percent' THEN round(subtotal * cp.discount_value / 100, 2) ELSE cp.discount_value END); UPDATE public.orders SET total_amount = subtotal - discount, discount_amount = discount, coupon_id = cp.id WHERE id = created_id; UPDATE public.customer_coupons SET used_at = now() WHERE id = cp.id; END IF; UPDATE public.orders SET user_id = owner_id WHERE id = created_id; RETURN created_id; END; $$;
REVOKE ALL ON FUNCTION public.create_owned_order(jsonb, jsonb, uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_owned_order(jsonb, jsonb, uuid, text) TO service_role;
CREATE OR REPLACE FUNCTION public.cancel_customer_order(order_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE target public.orders; item public.order_items; BEGIN SELECT * INTO target FROM public.orders WHERE id = order_id FOR UPDATE; IF target.id IS NULL OR target.user_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF; IF target.status <> 'pending' THEN RAISE EXCEPTION 'Only pending orders can be cancelled'; END IF; UPDATE public.orders SET status = 'cancelled' WHERE id = order_id; IF target.coupon_id IS NOT NULL THEN UPDATE public.customer_coupons SET used_at = NULL WHERE id = target.coupon_id; END IF; FOR item IN SELECT * FROM public.order_items WHERE order_items.order_id = target.id LOOP IF item.variation_id IS NOT NULL THEN UPDATE public.product_variations SET stock = stock + item.quantity WHERE id = item.variation_id; ELSE UPDATE public.products SET stock = stock + item.quantity WHERE id = item.product_id; END IF; END LOOP; END; $$;
